mapper.select:
SELECT no, test_key AS testKey, test_id AS testId, test_title AS testTitle, result_id AS resultId, result_code AS resultCode, result_title AS resultTitle, result_image AS resultImage, score, user_id AS userId, anon_id AS anonId, created_at AS createdAt FROM moondap.md_test_history
WHERE user_id = #{userId}
WHERE anon_id = #{anonId} AND user_id IS NULL
WHERE 1 = 0
ORDER BY created_at DESC, no DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE moondap.md_test_history
   SET user_id = #{userId}
 WHERE anon_id = #{anonId}
   AND user_id IS NULL

mapper.delete:
DELETE FROM moondap.md_test_history
WHERE no = #{no}


        AND user_id = #{userId}


        AND anon_id = #{anonId} AND user_id IS NULL


        AND 1 = 0
